@register.simple_tag
def icon(name, size=20, label=""):
    """Inline SVG icon. Decorative unless a label is given."""
    accessibility = format_html('role="img" aria-label="{}"', label) if label else mark_safe('aria-hidden="true"')
    return format_html('<svg class="icon icon-{}" width="{}" height="{}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" focusable="false" {}>{}</svg>', name, size, size, accessibility, mark_safe(ICONS[name]))
# Familiar language colors (values as used by GitHub Linguist); unknown languages get a neutral gray.
LANGUAGE_COLORS = {"Python": "#3572A5", "JavaScript": "#f1e05a", "TypeScript": "#3178c6", "HTML": "#e34c26", "CSS": "#663399", "SCSS": "#c6538c", "Go": "#00ADD8", "Java": "#b07219", "Kotlin": "#A97BFF", "Rust": "#dea584", "C": "#555555", "C++": "#f34b7d", "C#": "#178600", "Ruby": "#701516", "PHP": "#4F5D95", "Shell": "#89e051", "Swift": "#F05138", "Dart": "#00B4AB", "Vue": "#41b883", "Svelte": "#ff3e00", "SQL": "#e38c00", "Jupyter Notebook": "#DA5B0B", "Dockerfile": "#384d54", "Elixir": "#6e4a7e", "Scala": "#c22d40", "R": "#198CE7", "Lua": "#000080"}
@register.filter
def language_color(name):
    return LANGUAGE_COLORS.get(name, "#8b949e")
@register.filter
def top_language(languages):
    return next(iter(languages or {}), "")
@register.filter
def initials(user):
    """Two-letter avatar text from the person's name, falling back to their public handle."""
    letters = (getattr(user, "first_name", "")[:1] + getattr(user, "last_name", "")[:1]).upper()
    if letters:
        return letters
    profile = getattr(user, "profile", None)
    return (getattr(profile, "handle", "") or "?")[:2].upper()
def _logo(user):
    profile = getattr(user, "profile", None) if user is not None else None
    avatar = getattr(profile, "avatar", None)
    return avatar if avatar else None
@register.filter
def face(subject):
    """What goes inside an avatar or logo circle: the uploaded logo or photo, else initials.
    Works for people and for organizations, whose logo is their institute account's logo."""
    if hasattr(subject, "invite_code"):  # an organization
        logo = _logo(subject.owner)
        return format_html('<img src="{}" alt="" loading="lazy" decoding="async">', logo.url) if logo else subject.initials
    logo = _logo(subject)
    return format_html('<img src="{}" alt="" loading="lazy" decoding="async">', logo.url) if logo else initials(subject)
@register.filter
def ago(moment):
    """When something happened, for logs: "just now", or "5 minutes ago"."""
    from django.utils import timezone
    from django.utils.timesince import timesince
    if moment is None:
        return ""
    return "just now" if (timezone.now() - moment).total_seconds() < 60 else f"{timesince(moment)} ago"
@register.filter
def public_name(user):
    """How to name someone to people who aren't staff: their name, else their public handle. Never their email."""
    profile = getattr(user, "profile", None)
    return user.get_full_name() or (f"@{profile.handle}" if profile and profile.handle else "A MyProgress member")
@register.filter
def clock(seconds):
    """A video's length the way players show it: 4:05, or 1:02:03."""
    hours, rest = divmod(int(seconds or 0), 3600)
    minutes, secs = divmod(rest, 60)
    return f"{hours}:{minutes:02d}:{secs:02d}" if hours else f"{minutes}:{secs:02d}"
@register.filter
def tone(obj):
    """Stable muted background tone (tone-0..tone-5) for items without an image."""
    return f"tone-{(getattr(obj, 'pk', 0) or 0) % 6}"
@register.filter
def avatar_tone(user):
    """Stable pastel color class (av-0..av-7) for a person's initials."""
    return f"av-{(getattr(user, 'pk', 0) or 0) % 8}"
